    "accessTier": "premium",
    "isFree": false,
    "xpReward": 55,
    "orderIndex": 70,
    "estimatedMinutes": 28,
    "description": "Lecture C2 pour interpréter feedback correctif et traitement de l’erreur avec précision et nuance.",
    "intro": "Lecture C2 pour interpréter feedback correctif et traitement de l’erreur avec précision et nuance.",
    "mission": "",
    "grammar": "",
    "phrases": [],
    "vocabulary": [],
